<!doctype html><meta charset="utf-8"><title>Quiz flow test</title>
<iframe id="app" src="/index.html" style="width:1200px;height:900px"></iframe>
<pre id="result">RUNNING</pre>
<script>
const result = document.querySelector('#result');
const frame = document.querySelector('#app');
frame.addEventListener('load', () => {
  try {
    const d = frame.contentDocument;
    const click = selector => d.querySelector(selector).click();
    const text = selector => d.querySelector(selector).textContent;
    click('#start-button');
    click('.chapter-card');
    let revised = false;
    for (let question = 0; question < 5; question++) {
      let doors = [...d.querySelectorAll('.answer-door')];
      doors[0].click();
      if (text('#feedback-status').includes('A DETOUR')) {
        d.querySelector('#analogy-input').value = question === 0 ? 'A careful first comparison.' : 'A meaningful comparison idea.';
        click('#analogy-submit');
        if (!d.querySelector('#analogy-review').textContent.includes('Limit check')) throw Error('analogy review missing self-check');
        if (question === 0) {
          click('.analogy-revise');
          d.querySelector('#analogy-input').value = 'A revised analogy with a clearer mapping.';
          click('#analogy-submit');
          if (!d.querySelector('#analogy-review').textContent.includes('A revised analogy')) throw Error('analogy revision not displayed');
          revised = true;
        }
      } else if (question === 0) {
        click('#review-button');
        for (let i = 1; i < doors.length; i++) {
          [...d.querySelectorAll('.answer-door')][i].click();
          if (text('#feedback-status').includes('A DETOUR')) {
            d.querySelector('#analogy-input').value = 'A careful first comparison.';
            click('#analogy-submit');
            click('.analogy-revise');
            d.querySelector('#analogy-input').value = 'A revised analogy with a clearer mapping.';
            click('#analogy-submit');
            if (!d.querySelector('#analogy-review').textContent.includes('A revised analogy')) throw Error('analogy revision not displayed');
            revised = true;
            break;
          }
          if (i < doors.length - 1) click('#review-button');
        }
        if (!revised) throw Error('could not reach wrong-answer analogy path');
      }
      click('#continue-button');
    }
    if (d.querySelector('#complete-screen').classList.contains('hidden')) throw Error('completion screen did not show');
    result.textContent = JSON.stringify({ok:true, questions:5, revisedAnalogy:revised, finalScore:text('#final-score')});
  } catch (error) {
    result.textContent = JSON.stringify({ok:false, error:String(error), stack:error.stack});
  }
});
</script>
EOF

